// Powers stock-analysis/fundamentals/template.html: reads ?symbol=TICKER
// from the URL, fetches /data/fundamentals/<TICKER>.json (generated by
// scripts/generate_fundamentals_data.py from the Fin statements MarketData
// pull) plus /data/fundamentals_index.json for peer comparison, and renders
// every section. No symbol in the URL -> empty-state search prompt; a
// symbol with no generated file -> "not available" state.
(function () {
  var els = {
    empty: document.getElementById("fund-empty"),
    notfound: document.getElementById("fund-notfound"),
    content: document.getElementById("fund-content"),
  };
  if (!els.content) return;

  function esc(s) {
    return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
  }

  function show(el) {
    if (el) el.hidden = false;
  }
  function hide(el) {
    if (el) el.hidden = true;
  }

  // ---------------- number formatting (Indian digit grouping, ₹ Cr scale) ----------------

  function indianGroup(intStr) {
    var neg = intStr.charAt(0) === "-";
    if (neg) intStr = intStr.slice(1);
    var last3 = intStr.slice(-3);
    var rest = intStr.slice(0, -3);
    if (rest !== "") {
      rest = rest.replace(/\B(?=(\d{2})+(?!\d))/g, ",");
      last3 = "," + last3;
    }
    return (neg ? "-" : "") + rest + last3;
  }

  function fmtNum(value, decimals) {
    if (value === null || value === undefined || isNaN(value)) return "—";
    var fixed = value.toFixed(decimals === undefined ? 0 : decimals);
    var dot = fixed.indexOf(".");
    if (dot === -1) return indianGroup(fixed);
    return indianGroup(fixed.slice(0, dot)) + fixed.slice(dot);
  }

  function fmtCr(rawValue, decimals) {
    if (rawValue === null || rawValue === undefined || isNaN(rawValue)) return "—";
    return fmtNum(rawValue / 1e7, decimals === undefined ? 0 : decimals);
  }

  function fmtPrice(value) {
    if (value === null || value === undefined || isNaN(value)) return "—";
    return "₹" + fmtNum(value, 2);
  }

  function fmtPercent(value, decimals) {
    if (value === null || value === undefined || isNaN(value)) return "—";
    return value.toFixed(decimals === undefined ? 2 : decimals) + "%";
  }

  function fmtRatio(value, decimals) {
    if (value === null || value === undefined || isNaN(value)) return "—";
    return value.toFixed(decimals === undefined ? 2 : decimals);
  }

  function fmtDays(value) {
    if (value === null || value === undefined || isNaN(value)) return "—";
    return Math.round(value) + "d";
  }

  function dirSpan(value, decimals, suffix) {
    if (value === null || value === undefined || isNaN(value)) return '<span class="dir flat">—</span>';
    var cls = value > 0 ? "up" : value < 0 ? "down" : "flat";
    var arrow =
      value > 0
        ? '<svg viewBox="0 0 24 24" fill="currentColor"><path d="M12 5l7 9H5z"/></svg>'
        : value < 0
        ? '<svg viewBox="0 0 24 24" fill="currentColor"><path d="M12 19l-7-9h14z"/></svg>'
        : "";
    var sign = value > 0 ? "+" : "";
    return '<span class="dir ' + cls + '">' + arrow + sign + value.toFixed(decimals === undefined ? 2 : decimals) + (suffix || "") + "</span>";
  }

  // ---------------- data fetch ----------------

  var params = new URLSearchParams(window.location.search);
  var symbol = (params.get("symbol") || "").trim().toUpperCase();

  if (!symbol) {
    show(els.empty);
    return;
  }

  Promise.all([
    fetch("/data/fundamentals/" + encodeURIComponent(symbol) + ".json").then(function (res) {
      if (!res.ok) throw new Error("HTTP " + res.status);
      return res.json();
    }),
    fetch("/data/fundamentals_index.json")
      .then(function (res) {
        return res.ok ? res.json() : [];
      })
      .catch(function () {
        return [];
      }),
  ])
    .then(function (results) {
      render(results[0], results[1]);
    })
    .catch(function () {
      show(els.notfound);
    });

  // ---------------- render ----------------

  function render(doc, index) {
    document.title = doc.name + " — Fundamentals — SnapStocks";
    var descMeta = document.querySelector('meta[name="description"]');
    if (descMeta) descMeta.setAttribute("content", "Full fundamentals snapshot for " + doc.symbol + ", generated from yfinance.");

    renderIdentity(doc);
    renderStats(doc, index);
    renderStatementTable("quarterly-table", doc.quarterly, "Quarter", quarterlyRowDefs(doc.quarterly));
    renderStatementTable("pl-table", doc.annual, "FY", annualRowDefs(doc));
    renderStatementTable("balance-sheet-table", doc.balanceSheet, "FY", balanceSheetRowDefs(doc.balanceSheet));
    renderStatementTable("cash-flow-table", doc.cashFlow, "FY", cashFlowRowDefs(doc.cashFlow));
    renderStatementTable("ratios-table", doc.ratios, "FY", ratiosRowDefs(doc.ratios));
    renderPeers(doc, index);

    show(els.content);
  }

  function renderIdentity(doc) {
    document.getElementById("fund-breadcrumb-current").textContent = doc.name + " — Fundamentals";
    document.getElementById("fund-logo").textContent = doc.symbol.slice(0, 2);
    document.getElementById("fund-name").textContent = doc.name;

    var pills = [];
    pills.push('<span class="pill pill-neutral"><span class="d"></span>NSE: ' + esc(doc.symbol) + "</span>");
    if (doc.profile.bseCode) pills.push('<span class="pill pill-neutral"><span class="d"></span>BSE: ' + esc(doc.profile.bseCode) + "</span>");
    if (doc.profile.sector) pills.push('<span class="pill pill-neutral"><span class="d"></span>' + esc(doc.profile.industry || doc.profile.sector) + "</span>");
    if (doc.profile.deepDiveUrl) {
      pills.push(
        '<a href="' + esc(doc.profile.deepDiveUrl) + '" class="pill pill-ai" style="text-decoration:none;"><span class="d"></span>Deep-dive report available</a>'
      );
    }
    document.getElementById("fund-pills").innerHTML = pills.join("");

    document.getElementById("fund-price").textContent = fmtPrice(doc.price.current);
    var priceDirEl = document.getElementById("fund-price-dir");
    var chg = doc.price.change;
    priceDirEl.className = "dir " + (chg > 0 ? "up" : chg < 0 ? "down" : "flat");
    priceDirEl.style.cssText = "justify-content:flex-end; font-size:0.95rem;";
    var arrowSvg =
      chg > 0
        ? '<svg viewBox="0 0 24 24" fill="currentColor"><path d="M12 5l7 9H5z"/></svg>'
        : chg < 0
        ? '<svg viewBox="0 0 24 24" fill="currentColor"><path d="M12 19l-7-9h14z"/></svg>'
        : "";
    priceDirEl.innerHTML =
      arrowSvg +
      fmtRatio(chg, 2) +
      (doc.price.changePercent !== null ? " (" + fmtRatio(doc.price.changePercent, 2) + "%) today" : "");

    var asOf = doc.price.asOf ? new Date(doc.price.asOf * 1000).toLocaleString("en-IN", { day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit" }) : null;
    document.getElementById("fund-asof").textContent = (asOf ? "As of " + asOf + " IST" : "") + " · generated " + new Date(doc.generatedAt).toLocaleDateString("en-IN", { day: "2-digit", month: "short", year: "numeric" });

    var low = doc.price.fiftyTwoWeekLow,
      high = doc.price.fiftyTwoWeekHigh,
      cur = doc.price.current;
    if (low !== null && high !== null && cur !== null && high > low) {
      var pctPos = Math.min(100, Math.max(0, ((cur - low) / (high - low)) * 100));
      document.getElementById("fund-range-fill").style.cssText = "left:0; width:" + pctPos + "%;";
      document.getElementById("fund-range-marker").style.left = pctPos + "%";
      document.getElementById("fund-range-low").textContent = "52W Low ₹" + fmtNum(low, 2);
      document.getElementById("fund-range-high").textContent = "52W High ₹" + fmtNum(high, 2);
      document.getElementById("fund-range").hidden = false;
    }
  }

  function renderStats(doc, index) {
    var s = doc.stats;
    var indexRow = index.filter(function (r) {
      return r.symbol === doc.symbol;
    })[0];
    var sectorMedianPE = indexRow ? indexRow.sectorMedianPE : null;

    var tiles = [
      ["Market Cap", "₹" + fmtCr(s.marketCap) + " Cr", null],
      ["P/E (TTM)", fmtRatio(s.trailingPE), sectorMedianPE ? "Sector median " + fmtRatio(sectorMedianPE) : null],
      ["Book Value", fmtPrice(s.bookValue), null],
      ["P/B", fmtRatio(s.priceToBook), null],
      ["Dividend Yield", fmtPercent(s.dividendYield), null],
      ["ROCE", fmtPercent(s.roce), null],
      ["ROE", fmtPercent(s.roe), null],
      ["Debt / Equity", fmtRatio(s.debtToEquity), null],
      ["EPS (TTM)", fmtPrice(s.trailingEps), null],
      ["1Y Return", fmtRatio(s.return1y) + "%", null],
    ];
    document.getElementById("fund-stats").innerHTML = tiles
      .map(function (t) {
        return '<div class="stat"><div class="k">' + esc(t[0]) + '</div><div class="v">' + t[1] + "</div>" + (t[2] ? '<div class="d">' + esc(t[2]) + "</div>" : "") + "</div>";
      })
      .join("");
  }

  // ---------------- statement table row definitions ----------------

  function quarterlyRowDefs(block) {
    if (!block) return [];
    var r = block.rows;
    return [
      { label: "Sales", values: r.Sales, fmt: fmtCr },
      { label: "Expenses", values: r.Expenses, fmt: fmtCr },
      { label: "Operating Profit", values: r.OperatingProfit, fmt: fmtCr },
      { label: "OPM %", values: opm(r.OperatingProfit, r.Sales), fmt: fmtPercent },
      { label: "Net Profit", values: r.NetProfit, fmt: fmtCr },
      { label: "EPS (₹)", values: r.EPS, fmt: function (v) { return fmtRatio(v, 2); } },
    ];
  }

  function annualRowDefs(doc) {
    var block = doc.annual;
    if (!block) return [];
    var r = block.rows;
    return [
      { label: "Sales", values: r.Sales, fmt: fmtCr, ttm: block.ttm ? block.ttm.Sales : null },
      { label: "Sales Growth %", values: r.SalesGrowth, fmt: fmtPercent, ttm: null },
      { label: "Operating Profit", values: r.OperatingProfit, fmt: fmtCr, ttm: block.ttm ? block.ttm.OperatingProfit : null },
      { label: "OPM %", values: opm(r.OperatingProfit, r.Sales), fmt: fmtPercent, ttm: block.ttm ? opm([block.ttm.OperatingProfit], [block.ttm.Sales])[0] : null },
      { label: "Net Profit", values: r.NetProfit, fmt: fmtCr, ttm: block.ttm ? block.ttm.NetProfit : null },
      { label: "EPS (₹)", values: r.EPS, fmt: function (v) { return fmtRatio(v, 2); }, ttm: doc.stats.trailingEps },
    ];
  }

  function balanceSheetRowDefs(block) {
    if (!block) return [];
    var r = block.rows;
    var reserves = r.StockholdersEquity.map(function (eq, i) {
      var cap = r.EquityCapital[i];
      return eq === null || cap === null ? null : eq - cap;
    });
    return [
      { label: "Equity Capital", values: r.EquityCapital, fmt: fmtCr },
      { label: "Reserves", values: reserves, fmt: fmtCr },
      { label: "Borrowings", values: r.Borrowings, fmt: fmtCr },
      { label: "Total Liabilities", values: r.TotalAssets, fmt: fmtCr },
      { label: "Net Block", values: r.NetBlock, fmt: fmtCr },
      { label: "Investments", values: r.Investments, fmt: fmtCr },
      { label: "Total Assets", values: r.TotalAssets, fmt: fmtCr },
    ];
  }

  function cashFlowRowDefs(block) {
    if (!block) return [];
    var r = block.rows;
    return [
      { label: "Cash from Operations", values: r.OperatingCashFlow, fmt: fmtCr },
      { label: "Cash from Investing", values: r.InvestingCashFlow, fmt: fmtCr },
      { label: "Cash from Financing", values: r.FinancingCashFlow, fmt: fmtCr },
      { label: "Net Cash Flow", values: r.NetCashFlow, fmt: fmtCr },
    ];
  }

  function ratiosRowDefs(block) {
    if (!block) return [];
    var r = block.rows;
    return [
      { label: "ROCE %", values: r.ROCE, fmt: fmtPercent },
      { label: "ROE %", values: r.ROE, fmt: fmtPercent },
      { label: "Debtor Days", values: r.DebtorDays, fmt: fmtDays },
      { label: "Working Capital Days", values: r.WorkingCapitalDays, fmt: fmtDays },
    ];
  }

  function opm(operatingProfit, sales) {
    return (operatingProfit || []).map(function (op, i) {
      var s = sales ? sales[i] : null;
      return op === null || s === null || !s ? null : (op / s) * 100;
    });
  }

  function renderStatementTable(elId, block, periodHeader, rowDefs) {
    var el = document.getElementById(elId);
    if (!el) return;
    var wrap = el.closest(".card");
    if (!block || !rowDefs.length) {
      if (wrap) wrap.hidden = true;
      return;
    }
    var periods = block.periods.slice();
    var hasTtm = rowDefs.some(function (r) {
      return r.ttm !== undefined;
    });
    var headerCells = periods.map(function (p) { return "<th>" + esc(p) + "</th>"; }).join("");
    if (hasTtm) headerCells += "<th>TTM</th>";

    var bodyRows = rowDefs
      .map(function (r) {
        var cells = r.values.map(function (v) { return "<td>" + r.fmt(v) + "</td>"; }).join("");
        if (hasTtm) cells += "<td>" + (r.ttm !== undefined && r.ttm !== null ? r.fmt(r.ttm) : "—") + "</td>";
        return '<tr><td class="name-cell">' + esc(r.label) + "</td>" + cells + "</tr>";
      })
      .join("");

    el.innerHTML =
      '<div class="table-scroll"><table class="data"><thead><tr><th>' +
      esc(periodHeader) +
      "</th>" +
      headerCells +
      "</tr></thead><tbody>" +
      bodyRows +
      "</tbody></table></div>";
  }

  function renderPeers(doc, index) {
    var wrap = document.getElementById("peers-table") && document.getElementById("peers-table").closest(".card");
    var group = doc.profile.peerIndustry || doc.profile.peerSector;
    var peers = index
      .filter(function (r) {
        return (r.industry || r.sector) === group && r.marketCap !== null;
      })
      .sort(function (a, b) {
        return (b.marketCap || 0) - (a.marketCap || 0);
      })
      .slice(0, 5);

    if (!group || peers.length < 2) {
      if (wrap) wrap.hidden = true;
      return;
    }

    var rows = peers
      .map(function (p) {
        var isSelf = p.symbol === doc.symbol;
        var nameCell = isSelf ? "<b>" + esc(p.name) + "</b>" : esc(p.name);
        return (
          '<tr><td class="name-cell">' +
          nameCell +
          "</td><td>" +
          fmtPrice(p.price) +
          "</td><td>" +
          fmtRatio(p.peTTM) +
          "</td><td>" +
          fmtCr(p.marketCap) +
          "</td><td>" +
          fmtPercent(p.roe) +
          "</td><td>" +
          dirSpan(p.return1y, 1, "%") +
          "</td></tr>"
        );
      })
      .join("");

    document.getElementById("peers-table").innerHTML =
      '<div class="table-scroll"><table class="data"><thead><tr><th>Company</th><th>CMP</th><th>P/E</th><th>Mkt Cap (₹Cr)</th><th>ROE %</th><th>1Y Return</th></tr></thead><tbody>' +
      rows +
      "</tbody></table></div>";
    document.getElementById("peers-desc").textContent = group + ", by market cap";
  }

  // ---------------- in-page tab active state ----------------
  document.querySelectorAll(".in-tabs a").forEach(function (a) {
    a.addEventListener("click", function () {
      document.querySelectorAll(".in-tabs a").forEach(function (x) { x.classList.remove("active"); });
      a.classList.add("active");
    });
  });
})();
